# --- Structural Integrity Tests ---------------------------------------------

class TestStructuralIntegrity:
    """Verify the config file is a valid, well-formed CommonJS module."""

    def test_file_exists(self):
        assert CONFIG_PATH.exists(), "tailwind.config.js must exist"

    def test_commonjs_export(self, config_source):
        """Ensure the file uses module.exports with an object literal."""
        assert "module.exports" in config_source
        assert re.search(r"module\.exports\s*=\s*\{", config_source)

    def test_config_is_object(self, config_module):
        assert isinstance(config_module, dict)

    def test_required_top_level_keys(self, config_module):
        """Tailwind v3+ requires 'content' and 'theme' keys."""
        required = {"content", "theme"}
        assert required.issubset(config_module.keys()), (
            f"Missing keys: {required - config_module.keys()}"
        )

    def test_optional_keys_valid(self, config_module):
        """'plugins' must be a list if present."""
        if "plugins" in config_module:
            assert isinstance(config_module["plugins"], list)


# --- Content Configuration Tests --------------------------------------------

class TestContentConfiguration:
    """Validate file glob patterns for Tailwind's content scanner."""

    def test_content_is_list(self, config_module):
        assert isinstance(config_module["content"], list)

    def test_content_not_empty(self, config_module):
        assert len(config_module["content"]) > 0, "Content paths must not be empty"

    def test_content_glob_patterns(self, config_module):
        """Ensure glob patterns target source files and HTML entry points."""
        patterns = config_module["content"]
        assert any("src/**/*" in p for p in patterns), (
            "Expected a glob for src directory"
        )
        assert any("public/index.html" in p for p in patterns), (
            "Expected public/index.html in content"
        )

    def test_content_extensions(self, config_module):
        """Verify JS/JSX/TS/TSX extensions are covered."""
        combined = " ".join(config_module["content"])
        for ext in ["js", "jsx", "ts", "tsx"]:
            assert f".{ext}" in combined, f"Missing extension .{ext} in content globs"

    def test_no_duplicate_content_entries(self, config_module):
        assert len(config_module["content"]) == len(set(config_module["content"])), (
            "Duplicate content entries detected"
        )


# --- Theme Extension Tests ---------------------------------------------------

class TestThemeExtension:
    """Validate custom design tokens in the theme.extend block."""

    def test_theme_has_extend(self, config_module):
        assert "extend" in config_module["theme"], "Theme must have an extend block"

    def test_theme_extend_is_dict(self, config_module):
        assert isinstance(config_module["theme"]["extend"], dict)

    def test_color_tokens_present(self, config_module):
        """All Swarm OS color tokens must be defined."""
        expected_colors = {
            "swarm-dark",
            "swarm-medium",
            "swarm-light",
            "swarm-accent",
            "swarm-success",
            "swarm-warning",
            "swarm-danger",
        }
        colors = config_module["theme"]["extend"].get("colors", {})
        assert expected_colors.issubset(colors.keys()), (
            f"Missing colors: {expected_colors - colors.keys()}"
        )

    def test_color_values_are_valid_hex(self, config_module):
        """All color values must be 6-digit hex codes."""
        colors = config_module["theme"]["extend"].get("colors", {})
        hex_pattern = re.compile(r"^#[0-9a-fA-F]{6}$")
        for name, value in colors.items():
            assert hex_pattern.match(value), (
                f"Color '{name}' has invalid hex value: {value}"
            )

    def test_color_semantic_accuracy(self, config_module):
        """Spot-check semantic color values against expected design tokens."""
        colors = config_module["theme"]["extend"]["colors"]
        assert colors["swarm-dark"] == "#1a202c"
        assert colors["swarm-accent"] == "#63b3ed"
        assert colors["swarm-danger"] == "#fc8181"

    def test_font_family_sans(self, config_module):
        """Ensure Inter is the primary sans-serif font."""
        fonts = config_module["theme"]["extend"].get("fontFamily", {})
        assert "sans" in fonts
        assert fonts["sans"] == ["Inter", "sans-serif"]

    def test_no_unknown_theme_keys(self, config_module):
        """Prevent accidental theme misconfiguration."""
        allowed_extend_keys = {"colors", "fontFamily"}
        extend_keys = set(config_module["theme"]["extend"].keys())
        assert extend_keys.issubset(allowed_extend_keys), (
            f"Unexpected theme.extend keys: {extend_keys - allowed_extend_keys}"
        )


