class TestPluginsAndMisc:
    """Validate plugin array and general config sanity."""

    def test_plugins_is_empty_list(self, config_module):
        """Current config declares no plugins; enforce this invariant."""
        assert config_module.get("plugins", []) == []

    def test_no_unsafe_config(self, config_module):
        """Ensure no dangerous or deprecated keys are present."""
        forbidden = {"important", "separator", "corePlugins"}
        assert not forbidden.intersection(config_module.keys()), (
            f"Forbidden keys present: {forbidden & config_module.keys()}"
        )

    def test_config_serializable(self, config_module):
        """Config must be JSON-serializable for tooling compatibility."""
        import json

        try:
            json.dumps(config_module)
        except TypeError as exc:
            pytest.fail(f"Config is not JSON-serializable: {exc}")

    def test_source_has_no_trailing_whitespace(self, config_source):
        """Enforce clean code style."""
        for line_no, line in enumerate(config_source.splitlines(), 1):
            assert not line.rstrip() != line, (
                f"Trailing whitespace on line {line_no}"
            )


# --- Edge-Case & Defensive Tests --------------------------------------------

class TestEdgeCases:
    """Defensive checks for common misconfigurations."""

    def test_content_paths_exist(self, config_module):
        """Warn if referenced paths do not exist in the project (non-fatal)."""
        base_dir = CONFIG_PATH.parent
        for pattern in config_module["content"]:
            # Only check static paths, not globs
            if "*" not in pattern:
                path = base_dir / pattern
                assert path.exists(), (
                    f"Referenced path does not exist: {pattern}"
                )

    def test_theme_not_override_core(self, config_module):
        """Ensure extend does not accidentally override core Tailwind tokens."""
        extend = config_module["theme"]["extend"]
        # 'colors' and 'fontFamily' are safe to extend; ensure no core keys like
        # 'screens', 'spacing', etc. are being overridden.
        core_theme_keys = {"screens", "spacing", "borderRadius", "boxShadow"}
        assert not core_theme_keys.intersection(extend.keys()), (
            "Theme extension must not override core Tailwind keys"
        )

    def test_hex_color_uniqueness(self, config_module):
        """Ensure no duplicate color values (design consistency)."""
        colors = config_module["theme"]["extend"]["colors"]
        values = list(colors.values())
        assert len(values) == len(set(values)), "Duplicate color values detected"

    def test_font_family_no_duplicates(self, config_module):
        """Font stack should not have duplicate entries."""
        sans = config_module["theme"]["extend"]["fontFamily"]["sans"]
        assert len(sans) == len(set(sans)), "Duplicate font family entries"

    def test_config_has_no_comments_in_json(self, config_source):
        """Ensure no JS-style comments leak into the exported object."""
        # Strip the header comment and check the object body
        body = config_source.split("module.exports", 1)[-1]
        assert "//" not in body, "JS comments found in config body"
        assert "/*" not in body, "Block comments found in config body"


